      "find /tmp -type f -delete",
      "find . -name '*.tmp' -exec rm {} \\;",
      "find . -name '*.o' -exec rm -rf {} +",
      "find . -type d -empty -delete",
      "find . -name '*.pyc' | xargs rm -f",
      "find / -mtime +30 -delete",
      "find . -name '*~' | xargs rm",
